# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundSpansTests(unittest.TestCase):
    def test_label_format(self):
        self.assertEqual(
            round_spans([Span(540, 1035)], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_to_nearest(self):
        # 09:07 -> 09:00, 17:08 -> 17:15 on a fifteen step
        self.assertEqual(
            round_spans([Span(547, 1028)], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_halfway_rounds_up(self):
        self.assertEqual(
            round_spans([Span(545, 600)], 10),
            ["09:10-10:00 (0h 50m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                round_spans([Span(60, 120)], step)


if __name__ == "__main__":
    unittest.main()
